#!/usr/bin/env bash
# fresh_build.sh — clean-room release build gate. Run from an EMPTY directory into which the
# release `lean/` tree (lakefile.lean = release lakefile with git-pinned mathlib, lean-toolchain,
# MPUP/, DiophCompression/, scripts/; lake-manifest.json is generated by `lake update` and is not part of the manifest) has been copied; optionally
# `../frozen_statements/` and `../certificates/definition_bodies.tsv` for the two fidelity gates.
# Any failure aborts with non-zero exit (set -euo pipefail). Writes every sub-log under logs/.
set -euo pipefail
cd "$(dirname "$0")"
export PATH="$HOME/.elan/bin:$PATH"; ulimit -n 8192
mkdir -p logs
sha256_file() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | awk '{print $1}'; else shasum -a 256 "$1" | awk '{print $1}'; fi; }
manifest() { # canonical source manifest: sorted (LC_ALL=C) list of "sha256  path" over all .lean/.py/.sh plus build metadata
  { find MPUP DiophCompression scripts -type f \( -name '*.lean' -o -name '*.py' -o -name '*.sh' \) -print0; printf '%s\0' MPUP.lean DiophCompression.lean lakefile.lean lean-toolchain; } \
    | LC_ALL=C sort -z | while IFS= read -r -d '' f; do printf '%s  %s\n' "$(sha256_file "$f")" "$f"; done; }
echo "=== FRESH-CLONE RELEASE BUILD (release lakefile, empty dir, set -euo pipefail) ==="; date; hostname; pwd
echo "--- lean-toolchain ---"; cat lean-toolchain
echo "--- lakefile.lean ---"; cat lakefile.lean
manifest > logs/source_manifest_start.sha256
echo "SOURCE_MANIFEST_FILES=$(wc -l < logs/source_manifest_start.sha256 | tr -d ' ')"
echo "SRC_MANIFEST_SHA256=$(sha256_file logs/source_manifest_start.sha256)"
echo "=== lake update (fetch mathlib at pin) ==="; lake update > logs/lake_update.log 2>&1; echo "UPDATE_EXIT=0"; tail -3 logs/lake_update.log
echo "=== manifest mathlib rev ==="; python3 -c "import json;m=json.load(open('lake-manifest.json'));print('MATHLIB_REV=' + str([(p.get('rev'),p.get('inputRev')) for p in m['packages'] if p['name']=='mathlib']))"
echo "=== lake exe cache get ==="; lake exe cache get > logs/cache_get.log 2>&1; echo "CACHE_EXIT=0"; tail -3 logs/cache_get.log
echo "=== plain lake build (default target) ==="; lake build > logs/lake_build_plain.log 2>&1; echo "PLAIN_BUILD_EXIT=0"; tail -3 logs/lake_build_plain.log
echo "=== lake build DiophCompression ==="; lake build DiophCompression > logs/lake_build_dc.log 2>&1; echo "DC_BUILD_EXIT=0"; tail -3 logs/lake_build_dc.log
echo "=== lake build DiophCompression.QuadraticWitnessInertiaCore (all-r root) ==="; lake build DiophCompression.QuadraticWitnessInertiaCore > logs/minimal_all_r_build.log 2>&1; echo "CORE_BUILD_EXIT=0"; tail -3 logs/minimal_all_r_build.log
echo "=== rebuild.sh ==="; ./scripts/rebuild.sh > logs/rebuild.log 2>&1; echo "REBUILD_SH_EXIT=0"; grep -E "REBUILD_EXIT" logs/rebuild.log
echo "=== audit_dc.sh (per-file kernel audit + forbidden-token gate) ==="; ./scripts/audit_dc.sh > logs/audit_dc.log 2>&1; echo "AUDIT_SH_EXIT=0"; grep -E "AUDIT_EXIT" logs/audit_dc.log
echo "=== axiom multiset (env phase, rebuild + audit) ==="
grep 'depends on axioms' logs/rebuild.log logs/audit_dc.log | sed -E 's/.*depends on axioms: //' | sort | uniq -c
echo "forbidden tokens in axiom lines: $( (grep 'depends on axioms' logs/rebuild.log logs/audit_dc.log | grep -cE 'sorryAx|native_decide|ofReduceBool|trustCompiler') || true)"
if [ -d ../frozen_statements ]; then
  echo "=== statement fidelity (theorems + definition signatures) ==="; STMT_BASE=../frozen_statements LEAN_BASE=. python3 scripts/statement_diff.py > logs/statement_diff.log 2>&1 || { echo "STATEMENT_DIFF_EXIT=1"; exit 1; }; grep -E '^(FROZEN_FILES|THEOREMS|DEFINITIONS|OPEN_REGISTRY|DUPLICATE_NAMES|FAIL)=' logs/statement_diff.log; echo "STATEMENT_DIFF_EXIT=0"
  echo "=== statement_diff controls (planted faults + Unicode-subscript identifiers, s25 / GPT Gate-1 必須A-6) ==="; STMT_BASE=../frozen_statements LEAN_BASE=. python3 scripts/statement_diff.py --negative-control > logs/statement_diff_negctrl.log 2>&1 || { echo "STATEMENT_DIFF_NEGCTRL_EXIT=1"; exit 1; }; grep -E '^NEG_CONTROL' logs/statement_diff_negctrl.log; STMT_BASE=../frozen_statements LEAN_BASE=. python3 scripts/statement_diff.py --unicode-control > logs/statement_diff_unicode.log 2>&1 || { echo "STATEMENT_DIFF_UNICODE_EXIT=1"; exit 1; }; grep -E '^UNICODE_CONTROL' logs/statement_diff_unicode.log; echo "STATEMENT_DIFF_CONTROLS_EXIT=0"
else echo "STATEMENT_DIFF_SKIPPED=no ../frozen_statements"; fi
if [ -f ../certificates/definition_bodies.tsv ]; then
  echo "=== definition body fidelity (elaborated TYPE/VALUE hashes vs frozen certificate) ==="; python3 scripts/definition_fidelity.py --check ../certificates/definition_bodies.tsv > logs/definition_fidelity.log 2>&1 || { grep -E '^(DEFFID|MISMATCH|MISSING|EXTRA)' logs/definition_fidelity.log; echo "DEFFID_CHECK_EXIT=1"; exit 1; }; grep -E '^DEFFID' logs/definition_fidelity.log; echo "DEFFID_CHECK_EXIT=0"
else echo "DEFFID_SKIPPED=no ../certificates/definition_bodies.tsv"; fi
echo "=== closures (static import / kernel constant dependency) ==="
lake env lean scripts/kernel_closure.lean > logs/kernel_closure.log 2>&1; echo "KERNEL_CLOSURE_LEAN_EXIT=0"; grep -oE 'KERNEL_CLOSURE_MODULES=[0-9]+ DC=[0-9]+ MPUP=[0-9]+|KERNEL_ABSENT [^ ]+=(YES|NO)' logs/kernel_closure.log
python3 scripts/static_closure.py --kernel-list logs/kernel_closure.log > logs/static_closure.log 2>&1; echo "STATIC_CLOSURE_PY_EXIT=0"; grep -E '^(STATIC_CLOSURE_MODULES|STATIC_CLOSURE_LOC|STATIC_ABSENT|KERNEL_SUBSET_STATIC|STATIC_ONLY_MODULES|STATIC_CLOSURE_EXIT)' logs/static_closure.log
python3 scripts/static_closure.py --negative-control | grep -E 'NEGATIVE_CONTROL'
echo "=== FINAL THEOREM AXIOM REPORT (sixteen exported theorems) ==="
lake env lean scripts/FinalAxiomReport.lean 2>&1 | tee logs/final_axioms.log; echo "FINAL_AXIOMS_EXIT=0"
# s28 gate fix: a root proved without any axiom prints "does not depend on any axioms" — stronger than
# std-3, but invisible to a plain 'depends on axioms' count. Count BOTH shapes, and report them apart.
python3 - logs/final_axioms.log <<'PYGATE'
import re, sys
t = open(sys.argv[1]).read()
std = {"propext", "Classical.choice", "Quot.sound"}
# One record per root. The axiom list may WRAP over several lines when the name is long, so parse the
# text, never line-by-line (s28: a line-based grep both miscounts and misjudges wrapped records).
withax = re.findall(r"' depends on axioms: \[(.*?)\]", t, re.S)
free   = len(re.findall(r"' does not depend on any axioms", t))
nonstd = 0
for ax in withax:
    names = {x.strip() for x in ax.replace("\n", " ").split(",") if x.strip()}
    if not names <= std:
        nonstd += 1
print("FINAL_AXIOM_LINES=%d" % (len(withax) + free))
print("FINAL_AXIOM_FREE_LINES=%d" % free)
print("FINAL_NONSTD3_LINES=%d" % nonstd)
PYGATE
echo "FINAL_STD3_ONLY=$( (grep -cE 'sorryAx|native_decide|ofReduceBool|trustCompiler' logs/final_axioms.log) || true)"
echo "=== post-build source freeze check (manifest at end == manifest at start) ==="
manifest > logs/source_manifest_end.sha256
if cmp -s logs/source_manifest_start.sha256 logs/source_manifest_end.sha256; then echo "SOURCE_FREEZE=OK"; else echo "SOURCE_FREEZE=DRIFT"; diff logs/source_manifest_start.sha256 logs/source_manifest_end.sha256 || true; exit 1; fi
cp logs/source_manifest_end.sha256 source_manifest.sha256
echo "SOURCE_MANIFEST_FILE=source_manifest.sha256 sha256=$(sha256_file source_manifest.sha256)"
date; echo "FRESH_RELEASE_DONE"
